function loginView(){const first=!DB.users.some(x=>x.role==='admin');$('#app').innerHTML=`<div class=login><div class=hero><h1>${ic('stu',28)} مدرسة د. أحمد زويل</h1><p>${first?'الإعداد الأول — أنشئ حساب المدير':'نظام إدارة المدرسة'}</p></div><div class=card>${first?'<label>اسم المدير</label><input id=ln>':''}<label>اسم المستخدم</label><input id=lu dir=ltr autocomplete=username autocapitalize=off autocorrect=off spellcheck=false><label style="margin-top:10px;display:block">كلمة المرور</label><input id=lp dir=ltr type=password autocomplete=current-password autocapitalize=off autocorrect=off spellcheck=false><button class=btn style="width:100%;margin-top:14px" onclick="doLogin()">${first?'إنشاء الحساب والدخول':'دخول'}</button></div><p style="text-align:center;color:var(--mu);font-size:11px">${(()=>{const c=x=>Object.keys(ROST).filter(k=>k[0]==x).reduce((n,k)=>n+ROST[k].list.length,0),a=c(1),b=c(2);return `إجمالي الطلاب: ${a+b} — الصف الأول: ${a} — الصف الثاني: ${b}`})()}</p>${LS?'':'<p style="text-align:center;color:var(--er);font-size:12px;margin-top:8px">تنبيه: المتصفح لا يحفظ البيانات في هذا الوضع، وستضيع الحسابات عند إغلاق الصفحة.</p>'}</div>`}
