 cell(R,t0,dw,hh,'اليوم','#0B3C6F','#fff',32);
 S.p.forEach((tm,i)=>cell(R-dw-i*cw,t0,cw,hh,'حصة '+(i+1),'#0B3C6F','#fff',30,tm));
 days.forEach((d,r)=>{const y=t0+hh+r*rh;cell(R,y,dw,rh,d,'#E8EEF7','#0B3C6F',32);S.p.forEach((_,p)=>cell(R-dw-p*cw,y,cw,rh,g('sub',(S.d[r]||[])[p]).name||'-',r%2?'#F7F9FC':'#fff','#14213D',30))});
