 off[4]=len;add('4 0 obj\n<</Type/XObject/Subtype/Image/Width '+W+'/Height '+H+'/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length '+jpg.length+'>>\nstream\n');add(jpg);add('\nendstream\nendobj\n');
 const cs='q 842 0 0 595 0 0 cm /I Do Q';obj(5,'<</Length '+cs.length+'>>\nstream\n'+cs+'\nendstream');
 const xr=len;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<6;i++)add(String(off[i]).padStart(10,'0')+' 00000 n \n');
