const dim=k=>{const[y,m]=k.split('-').map(Number);return new Date(y,m,0).getDate()};
function faMonths(){const last=[curYM(),FA_END,...Object.keys(FD().att)].sort().pop(),o=[];let[y,m]=FA_START.split('-').map(Number);for(;;){const k=y+'-'+String(m).padStart(2,'0');o.push(k);if(k>=last)break;if(++m>12){m=1;y++}}return o}
function faGate(t){return hd(t)+`<div class=card style="max-width:400px;margin:20px auto;text-align:center"><div style="color:var(--pr)">${ic('lock',40)}</div><b style="display:block;margin:8px 0">منطقة محمية بكلمة مرور</b><p style="color:var(--mu);font-size:13px;margin-bottom:12px">أدخلي كلمة مرور قسم الحضور للمتابعة، ثم اختاري السنة الدراسية والفصل.</p><input id=fpw type=password dir=ltr autocomplete=off onkeydown="if(event.key==='Enter')faUnlock()"><button class=btn style="width:100%;margin-top:12px" onclick="faUnlock()">فتح</button></div>`}
function faUnlock(){if(H(fpw.value.trim())!==FP())return toast('كلمة المرور غير صحيحة');FA.ok=1;save();app()}
function faTools(){return `<button class="btn g s" onclick="FA.cls=null;FA.q='';app()">${ic('cls',14)} تغيير الفصل</button><button class="btn g s" onclick="faPw()">${ic('key',14)} تغيير كلمة المرور</button><button class="btn g s" onclick="FA.ok=0;FA.cls=null;app()">${ic('lock',14)} قفل</button>`}
function faChoose(t){const g=FA.g,ks=Object.keys(ROST).filter(k=>k[0]==g);
 return hd(t,'<button class="btn g s" onclick="FA.ok=0;FA.cls=null;app()">'+ic('lock',14)+' قفل</button>')+`<div class=card style="max-width:560px;margin:10px auto"><b style="display:block;margin-bottom:6px">1) اختاري السنة الدراسية</b><div class=chips>${[1,2].map(x=>`<button class="btn ${x==g?'':'g'}" onclick="FA.g=${x};app()">${GN[x]}</button>`).join('')}</div>
 <b style="display:block;margin:14px 0 6px">2) اختاري الفصل</b><div class=chips>${ks.map(k=>`<button class="btn g" style="min-width:120px;padding:10px" onclick="FA.cls='${k}';FA.q='';app()"><b style="font-size:18px">${cl(k)}</b><small style="display:block;color:var(--mu)">${ROST[k].list.length} طالبة</small>${ROST[k].t?`<small style="display:block;color:var(--mu);font-size:11px">${ROST[k].t}</small>`:''}</button>`).join('')}</div></div>`}
function faPw(){form('تغيير كلمة مرور قسم الحضور',[{k:'o',l:'كلمة المرور الحالية',t:'password'},{k:'n',l:'كلمة المرور الجديدة (4 أحرف على الأقل)',t:'password'}],v=>{if(H(v.o.trim())!==FP())return toast('كلمة المرور الحالية غير صحيحة');if(v.n.trim().length<4)return toast('كلمة المرور قصيرة');DB.cfg.fp=H(v.n.trim());toast('تم تغيير كلمة المرور')})}
function faCell(v,d){return `<td class="c ${v||''}${[5,6].includes(d.w)?' we':''}" data-d=${d.d}>${v==='p'?'✓':v==='a'?'×':''}</td>`}
P.fa=()=>{if(!FA.ok)return faGate('حضور الفصول');if(!FA.cls)return faChoose('حضور الفصول');
 const ms=faMonths();if(!FA.ym||!ms.includes(FA.ym))FA.ym=ms.includes(curYM())?curYM():ms[0];
 const k=FA.ym,n=dim(k),F=FD(),at=F.att[k]||{},[y,m]=k.split('-').map(Number),ds=[...Array(n)].map((_,i)=>({d:i+1,w:new Date(y,m-1,i+1).getDay()}));
  const head=`<tr><th class=nmc>اسم الطالبة</th>${ds.map(d=>`<th class="dh${[5,6].includes(d.w)?' we':''}" data-d=${d.d} title="تحضير الجميع لهذا اليوم">${d.d}<small>${WD[d.w]}</small></th>`).join('')}<th class=tt style="background:var(--ok);color:#fff">حضور</th><th class=tt style="background:var(--er);color:#fff">غياب</th></tr>`;
 const rows=F.roster.map((s,i)=>{const o=at[s.id]||{};let p=0,a=0;for(const x in o)o[x]==='p'?p++:a++;
  return `<tr data-s="${eh(s.id)}" data-n="${eh(akey(s.name).toLowerCase())}"><td class=nmc title="${eh(s.name)}">${i+1}. ${eh(s.name)}</td>${ds.map(d=>faCell(o[d.d],d)).join('')}<td class="tt tp">${p}</td><td class="tt ta">${a}</td></tr>`}).join('');
 setTimeout(()=>faFilter(FA.q),0);
 return hd('حضور فصل '+cl(FA.cls)+' — '+GN[FA.cls[0]],faTools())+`<div class=card><div class=bar>${clSel()}<select onchange="FA.ym=this.value;app()">${ms.map(x=>`<option value=${x} ${x===k?'selected':''}>${ymLabel(x)}</option>`).join('')}</select><input id=faq placeholder="بحث باسم الطالبة" value="${eh(FA.q)}" oninput="faFilter(this.value)"><button class="btn g" onclick="faCsv('${k}')">${ic('dl',16)} تصدير ${ymLabel(k)}</button></div>
 <div class=fa-lg><span><i style="background:var(--ok)"></i>اضغطي على الخانة: حاضرة ✓</span><span><i style="background:var(--er)"></i>مرة أخرى: غائبة ×</span><span><i style="border:1px solid var(--bd)"></i>مرة ثالثة: تفريغ (إجازة / لم تُسجَّل)</span><span>اضغطي على رقم اليوم لتحضير الجميع حاضرات ثم عدّلي الغائبات فقط.</span></div>
 <div class=fas onclick="faClick(event)"><table class=fat><thead>${head}</thead><tbody>${rows}</tbody></table></div><p style="color:var(--mu);font-size:12px;margin-top:8px">الحفظ تلقائي لحظة كل ضغطة. عدد الطالبات: ${F.roster.length} — حسب كشف الفصل.</p></div>`};
const clSel=()=>`<select onchange="FA.cls=this.value;FA.q='';app()">${Object.keys(ROST).map(k=>`<option value=${k} ${k===FA.cls?'selected':''}>${GN[k[0]]} — فصل ${cl(k)}</option>`).join('')}</select>`;
function faFilter(q){FA.q=q||'';const t=akey(FA.q).toLowerCase();document.querySelectorAll('.fat tbody tr').forEach(r=>r.style.display=!t||r.dataset.n.includes(t)?'':'none')}
function faPaint(tr){const o=(FD().att[FA.ym]||{})[tr.dataset.s]||{};let p=0,a=0;for(const x in o)o[x]==='p'?p++:a++;
 tr.querySelectorAll('td.c').forEach(td=>{const v=o[td.dataset.d]||'';td.classList.toggle('p',v==='p');td.classList.toggle('a',v==='a');td.textContent=v==='p'?'✓':v==='a'?'×':''});
 tr.querySelector('.tp').textContent=p;tr.querySelector('.ta').textContent=a}
function faSet(id,d,v){const A=FD().att,k=FA.ym;A[k]=A[k]||{};const o=A[k][id]=A[k][id]||{};if(v)o[d]=v;else delete o[d];if(!Object.keys(o).length)delete A[k][id];if(!Object.keys(A[k]).length)delete A[k]}
function faClick(e){const td=e.target.closest('td.c'),th=e.target.closest('th.dh');
 if(td){const tr=td.parentNode,id=tr.dataset.s,d=td.dataset.d,cur=((FD().att[FA.ym]||{})[id]||{})[d]||'';faSet(id,d,cur===''?'p':cur==='p'?'a':'');save();faPaint(tr)}
 else if(th){const d=th.dataset.d,A=FD().att[FA.ym]||{},ids=FD().roster.map(s=>s.id),un=ids.filter(id=>!(A[id]||{})[d]);
  if(un.length){un.forEach(id=>faSet(id,d,'p'))}else{if(!confirm('كل الطالبات مسجّلات في هذا اليوم. هل تريدين مسح تسجيل اليوم '+d+' بالكامل؟'))return;ids.forEach(id=>faSet(id,d,''))}
  save();document.querySelectorAll('.fat tbody tr').forEach(faPaint)}}
function faStats(k){const F=FD(),at=F.att[k]||{},days=new Set();
 const rows=F.roster.map(s=>{const o=at[s.id]||{};let p=0,a=0;for(const x in o){days.add(x);o[x]==='p'?p++:a++}const t=p+a;return{s,p,a,t,pct:t?Math.round(p/t*1000)/10:null}});
 const w=rows.filter(r=>r.t),r1=x=>Math.round(x*10)/10;
 return{rows,days:days.size,n:w.length,avgPct:w.length?r1(w.reduce((x,r)=>x+r.pct,0)/w.length):null,avgP:w.length?r1(w.reduce((x,r)=>x+r.p,0)/w.length):null}}
const pcol=p=>p>=90?'':p>=75?' y':' r';
P.fr=()=>{if(!FA.ok)return faGate('تقرير الحضور');if(!FA.cls)return faChoose('تقرير الحضور');
 const F=FD();
 const ms=faMonths(),cur=curYM(),S={};ms.forEach(k=>S[k]=faStats(k));
 const done=ms.filter(k=>S[k].n&&k<cur),cs=S[cur]||{};
 const all=ms.filter(k=>S[k].n),yr=all.length?Math.round(all.reduce((a,k)=>a+S[k].avgPct,0)/all.length*10)/10:null;
 const stat=`<div class=bar>${clSel()}</div><div class=grid><div class=st><b>${F.roster.length}</b><span>عدد الطالبات</span></div><div class=st style="--c:var(--ok)"><b>${cs.avgPct==null?'—':cs.avgPct+'%'}</b><span>نسبة حضور ${ymLabel(cur)} حتى الآن</span></div><div class=st style="--c:var(--ac)"><b>${cs.days||0}</b><span>أيام مسجّلة هذا الشهر</span></div><div class=st style="--c:var(--pr2)"><b>${yr==null?'—':yr+'%'}</b><span>متوسط كل الشهور (${all.length})</span></div></div>`;
 const cards=ms.map(k=>{const s=S[k],st=k<cur?'مكتمل':k===cur?'جارٍ':'لم يبدأ',has=s.n>0;
  const head=`<summary><b style="font-size:16px;min-width:110px">${ymLabel(k)}</b><span class="tg ${k<cur?'':k===cur?'y':'r'}" ${k>cur?'style="background:var(--mu)"':''}>${st}</span>${has?`<span style="color:var(--mu);font-size:13px">${s.days} يوم مسجّل — متوسط أيام الحضور ${s.avgP} يوم</span><b style="margin-inline-start:auto;font-size:20px">${s.avgPct}%</b>`:'<span style="color:var(--mu);font-size:13px">لا توجد بيانات مسجّلة</span>'}${has?`<div class=pb style="flex-basis:100%"><i style="width:${s.avgPct}%"></i></div>`:''}</summary>`;
  if(!has)return `<details class=mo style="opacity:.7">${head.replace('<summary>','<summary style="cursor:default">')}</details>`;
  const body=tbl(['#','اسم الطالبة','أيام الحضور','أيام الغياب','نسبة الحضور'],s.rows.map((r,i)=>[i+1,eh(r.s.name),r.p,r.a,r.t?`<span class="tg${pcol(r.pct)}">${r.pct}%</span>`:'—']));
  return `<details class=mo ${k===cur||(k===done[done.length-1]&&!(S[cur]||{}).n)?'open':''}>${head}<div class=sc>${body}<div class=bar style="margin-top:10px"><button class="btn g s" onclick="faCsv('${k}')">${ic('dl',14)} تصدير ${ymLabel(k)}</button></div></div></details>`}).join('');
 return hd('تقرير حضور فصل '+cl(FA.cls),faTools()+'<button class="btn g s" onclick="faCsvAll()">'+ic('dl',14)+' تصدير كل الشهور</button>')+stat+`<p style="color:var(--mu);font-size:12px;margin-bottom:10px">تُحسب نسبة كل طالبة = أيام الحضور ÷ (أيام الحضور + أيام الغياب المسجّلة). ويُحتسب متوسط الشهر تلقائيًا ولا تُحذف الشهور السابقة.</p>`+cards};
function faDl(name,txt){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+txt],{type:'text/csv;charset=utf-8'}));a.download=name;a.click()}
const csvq=v=>'"'+String(v).replace(/"/g,'""')+'"';
function faCsv(k){const s=faStats(k);faDl('attendance-'+FA.cls+'-'+k+'.csv',[['الكود','اسم الطالبة','أيام الحضور','أيام الغياب','نسبة الحضور %'],...s.rows.map(r=>[r.s.id,r.s.name,r.p,r.a,r.pct==null?'':r.pct]),['','متوسط الشهر','',s.avgP==null?'':s.avgP,s.avgPct==null?'':s.avgPct]].map(r=>r.map(csvq).join(',')).join('\r\n'))}
function faCsvAll(){const ms=faMonths(),S={};ms.forEach(k=>S[k]=faStats(k));const ks=ms.filter(k=>S[k].n);
 faDl('attendance-'+FA.cls+'-all-months.csv',[['الكود','اسم الطالبة',...ks.map(ymLabel)],...FD().roster.map((s,i)=>[s.id,s.name,...ks.map(k=>{const r=S[k].rows[i];return r.pct==null?'':r.pct+'%'})]),['','متوسط الشهر',...ks.map(k=>S[k].avgPct+'%')]].map(r=>r.map(csvq).join(',')).join('\r\n'))}
// ===== درجات الفصول (داشبورد شهري لكل فصل) =====
const GM=()=>{const o=[];let[y,m]=FA_START.split('-').map(Number);for(;;){const k=y+'-'+String(m).padStart(2,'0');o.push(k);if(k>=FA_END)break;if(++m>12){m=1;y++}}return o};
const GR=(c,k)=>(((DB.fa||{}).g||{})[c]||{})[k]||{max:20,v:{}};
const GW=(c,k)=>{const f=DB.fa||(DB.fa={}),g=f.g||(f.g={}),a=g[c]||(g[c]={});return a[k]||(a[k]={max:20,v:{}})};
const r1=x=>Math.round(x*10)/10;
function gStats(c,k){const R=GR(c,k),max=+R.max||20,L=ROST[c].list,vals=L.map(s=>{const x=R.v[s.id];return x===undefined||x===''||x===null?null:+x}),got=vals.filter(x=>x!=null);
 const avg=got.length?r1(got.reduce((a,b)=>a+b,0)/got.length):null;
 return{max,n:L.length,got:got.length,abs:L.length-got.length,avg,pct:avg==null?null:r1(avg/max*100),hi:got.length?Math.max(...got):null,lo:got.length?Math.min(...got):null,pass:got.length?Math.round(got.filter(x=>x>=max/2).length/got.length*100):null,vals}}
const gTag=(v,max)=>{if(v==null)return '<span class="tg" style="background:var(--mu)">لم تحضر</span>';const p=v/max*100;return `<span class="tg${p>=65?'':p>=50?' y':' r'}">${grade(p)}</span>`};
const gCards=S=>`<div class=grid><div class=st><b>${S.n}</b><span>عدد الطالبات</span></div><div class=st style="--c:var(--ok)"><b>${S.got}</b><span>سُجّلت درجتها</span></div><div class=st style="--c:var(--mu)"><b>${S.abs}</b><span>لم تحضر (بدون درجة)</span></div><div class=st style="--c:var(--ac)"><b>${S.avg==null?'—':S.avg+' / '+S.max}</b><span>المتوسط ${S.pct==null?'':'('+S.pct+'%)'}</span></div><div class=st style="--c:var(--pr2)"><b>${S.hi==null?'—':S.hi}</b><span>أعلى درجة</span></div><div class=st style="--c:var(--er)"><b>${S.lo==null?'—':S.lo}</b><span>أقل درجة</span></div><div class=st style="--c:var(--ok)"><b>${S.pass==null?'—':S.pass+'%'}</b><span>نسبة النجاح</span></div></div>`;
const gOver=k=>`<div class=card><b>مقارنة الفصول — ${ymLabel(k)}</b><p style="color:var(--mu);font-size:12px;margin:4px 0 10px">متوسط الدرجات كنسبة مئوية. اضغطي على فصل لفتحه.</p>${Object.keys(ROST).map(c=>{const S=gStats(c,k);return `<div style="cursor:pointer;padding:8px 0;border-bottom:1px solid var(--bd)" onclick="FA.cls='${c}';app()"><div style="display:flex;gap:8px;align-items:center"><b style="min-width:46px;${c===FA.cls?'color:var(--ac)':''}">${cl(c)}</b><span style="color:var(--mu);font-size:12px;flex:1">${S.got?S.got+' من '+S.n+' — لم تحضر '+S.abs:'لا توجد درجات'}</span><b>${S.pct==null?'—':S.pct+'%'}</b></div><div class=pb><i style="width:${S.pct||0}%;${S.pct!=null&&S.pct<50?'background:var(--er)':''}"></i></div></div>`}).join('')}</div>`;
let GMo=null;
P.gd=()=>{if(!FA.ok)return faGate('درجات الفصول');if(!FA.cls)return faChoose('درجات الفصول');
 const ms=GM();if(!GMo||!ms.includes(GMo))GMo=ms.includes(curYM())?curYM():ms[0];
 const c=FA.cls,k=GMo,S=gStats(c,k),L=ROST[c].list;
 const rows=L.map((s,i)=>`<tr data-s="${s.id}"><td>${i+1}</td><td style="white-space:normal">${eh(s.name)}</td><td><input type=number inputmode=decimal min=0 max=${S.max} step=any value="${S.vals[i]??''}" placeholder="—" oninput="gSet('${s.id}',this)" onchange="gFix('${s.id}',this)"></td><td class=gt>${gTag(S.vals[i],S.max)}</td></tr>`).join('');
 const used=ms.filter(m=>gStats(c,m).got);
 const sheet=used.length?`<details class=mo><summary><b>كشف كل الشهور — فصل ${cl(c)}</b></summary><div class=sc><table><tr><th>#</th><th>الاسم</th>${used.map(m=>`<th>${ymLabel(m)}</th>`).join('')}<th>المتوسط %</th></tr>${L.map((s,i)=>{let t=0,n=0;const cells=used.map(m=>{const T=gStats(c,m),v=T.vals[i];if(v!=null){t+=v/T.max*100;n++}return `<td>${v==null?'<span style="color:var(--mu)">—</span>':v}</td>`}).join('');return `<tr><td>${i+1}</td><td>${eh(s.name)}</td>${cells}<td><b>${n?r1(t/n)+'%':'—'}</b></td></tr>`}).join('')}</table></div></details>`:'';
 return hd('درجات فصل '+cl(c)+' — '+GN[c[0]],faTools())+`<div class=card><div class=bar>${clSel()}<select onchange="GMo=this.value;app()">${ms.map(x=>`<option value=${x} ${x===k?'selected':''}>${ymLabel(x)}</option>`).join('')}</select><label style="display:flex;align-items:center;gap:6px;color:var(--mu);white-space:nowrap">الدرجة العظمى <input type=number id=gmax min=1 value=${S.max} style="width:80px" onchange="gMax(this.value)"></label><button class="btn g" onclick="gCsv()">${ic('dl',16)} تصدير</button></div><p style="color:var(--mu);font-size:12px">اكتبي درجة كل طالبة لشهر ${ymLabel(k)}. اترك الخانة فارغة لو الطالبة لم تحضر. الحفظ تلقائي.</p></div><div id=gst>${gCards(S)}</div><div class=card><b>رصد درجات ${ymLabel(k)}</b><div class=sc style="max-height:60vh;overflow:auto;margin-top:8px"><table><tr><th>#</th><th>اسم الطالبة</th><th>الدرجة</th><th>التقدير</th></tr>${rows}</table></div></div><div id=gov>${gOver(k)}</div>${sheet}`};
function gRefresh(){const S=gStats(FA.cls,GMo);$('#gst').innerHTML=gCards(S);$('#gov').innerHTML=gOver(GMo)}
function gSet(id,inp){const c=FA.cls,k=GMo,w=GW(c,k),max=+w.max||20;if(inp.value===''){delete w.v[id]}else{w.v[id]=Math.max(0,Math.min(max,+inp.value))}save();
 const S=gStats(c,k),tr=inp.closest('tr'),i=ROST[c].list.findIndex(s=>s.id===id);tr.querySelector('.gt').innerHTML=gTag(S.vals[i],S.max);gRefresh()}
function gFix(id,inp){const v=(GR(FA.cls,GMo).v)[id];if(v!==undefined&&+inp.value!==v){inp.value=v;toast('الدرجة لا تزيد عن الدرجة العظمى')}}
function gMax(v){v=+v;if(!(v>0))return toast('أدخلي درجة عظمى صحيحة');const w=GW(FA.cls,GMo);w.max=v;Object.keys(w.v).forEach(i=>{if(w.v[i]>v)w.v[i]=v});save();app()}
function gCsv(){const c=FA.cls,k=GMo,S=gStats(c,k);faDl('grades-'+c+'-'+k+'.csv',[['م','اسم الطالبة','الدرجة','من'],...ROST[c].list.map((s,i)=>[i+1,s.name,S.vals[i]==null?'لم تحضر':S.vals[i],S.max])].map(r=>r.map(csvq).join(',')).join('\r\n'))}
function thm(){const d=document.documentElement,n=d.dataset.theme==='light'?'dark':'light';d.dataset.theme=n;try{localStorage.setItem('zth',n)}catch(e){}app()}
try{document.documentElement.dataset.theme=localStorage.getItem('zth')||'dark'}catch(e){document.documentElement.dataset.theme='dark'}
// ===== مصروفات الصف الأول: سدّدت / لم تسدد / إعفاء =====
const FE_K=()=>Object.keys(ROST).filter(k=>k[0]==='1');
let FEc='1-1';
const FEG=c=>((DB.fa||{}).fee||{})[c]||{};
const FEL={p:['✓ سدّدت','var(--ok)','#fff'],u:['× لم تسدد','var(--er)','#fff'],e:['معفاة','var(--ac)','#1a1200']};
const feBtn=(id,v)=>{const l=FEL[v];return `<button class="btn s" style="min-width:110px;${l?`background:${l[1]};color:${l[2]};border:0`:'background:none;border:1px solid var(--bd);color:var(--mu)'}" onclick="feeClick('${id}',this)">${l?l[0]:'— لم يُسجَّل'}</button>`};
function feeCards(c){const o=FEG(c),L=ROST[c].list;let p=0,u=0,e=0;L.forEach(s=>{const v=o[s.id];v==='p'?p++:v==='u'?u++:v==='e'&&e++});const r=L.length-p-u-e;
 return `<div class=grid><div class=st><b>${L.length}</b><span>عدد الطالبات</span></div><div class=st style="--c:var(--ok)"><b>${p}</b><span>سدّدت</span></div><div class=st style="--c:var(--er)"><b>${u}</b><span>لم تسدد</span></div><div class=st style="--c:var(--ac)"><b>${e}</b><span>معفاة من المصاريف</span></div><div class=st style="--c:var(--mu)"><b>${r}</b><span>لم يُسجَّل بعد</span></div></div>`}
function feeView(){if(!ROST[FEc]||FEc[0]!=='1')FEc='1-1';const c=FEc,o=FEG(c),L=ROST[c].list;
 return hd('مصروفات الصف الأول — فصل '+cl(c),'<button class="btn" onclick="feeAll()">سدّد الكل</button><button class="btn g" onclick="feeCsv()">'+ic('dl',16)+' تصدير</button>')+
 `<div class=card><div class=bar><select onchange="FEc=this.value;app()">${FE_K().map(k=>`<option value=${k} ${k===c?'selected':''}>الصف الأول — فصل ${cl(k)}</option>`).join('')}</select></div><div class=fa-lg><span>اضغطي على اسم الطالبة: مرة = سدّدت ✓</span><span>مرتين = لم تسدد ×</span><span>3 مرات = معفاة من المصاريف</span><span>4 مرات = تفريغ</span></div></div><div id=fcd>${feeCards(c)}</div>
 <div class=card><div class=bar><input id=feq placeholder="بحث باسم الطالبة" oninput="feeFilter(this.value)"></div><div class=sc style="max-height:62vh;overflow:auto"><table><tr><th>#</th><th>اسم الطالبة</th><th>حالة المصروفات</th></tr>${L.map((s,i)=>`<tr data-n="${eh(akey(s.name).toLowerCase())}"><td>${i+1}</td><td style="white-space:normal">${eh(s.name)}</td><td>${feBtn(s.id,o[s.id])}</td></tr>`).join('')}</table></div></div>`}
function feeFilter(q){const t=akey(q||'').toLowerCase();document.querySelectorAll('#app tr[data-n]').forEach(r=>r.style.display=!t||r.dataset.n.includes(t)?'':'none')}
function feeClick(id,btn){const f=DB.fa||(DB.fa={}),F=f.fee||(f.fee={}),o=F[FEc]||(F[FEc]={}),cur=o[id]||'',nx={'':'p',p:'u',u:'e',e:''}[cur];
 if(nx)o[id]=nx;else delete o[id];save();btn.outerHTML=feBtn(id,nx);$('#fcd').innerHTML=feeCards(FEc)}
function feeAll(){const o=FEG(FEc),L=ROST[FEc].list,ch=L.filter(s=>o[s.id]&&o[s.id]!=='p').length;if(ch&&!confirm('سيتم تغيير حالة '+ch+' طالبة سبق تسجيلها (لم تسدد / معفاة) إلى «سدّدت». متابعة؟'))return;
 const f=DB.fa||(DB.fa={}),F=f.fee||(f.fee={}),n=F[FEc]||(F[FEc]={});L.forEach(s=>n[s.id]='p');save();app();toast('تم تسجيل الكل: سدّدت')}
function feeCsv(){const o=FEG(FEc),N={p:'سدّدت',u:'لم تسدد',e:'معفاة'};faDl('fees-'+FEc+'.csv',[['م','اسم الطالبة','الحالة'],...ROST[FEc].list.map((s,i)=>[i+1,s.name,N[o[s.id]]||'لم يُسجَّل'])].map(r=>r.map(csvq).join(',')).join('\r\n'))}
const _fee0=P.fee;P.fee=()=>U.role==='admin'?feeView():_fee0();
$('#modal').onclick=e=>{if(e.target.id==='modal')close()};
app();
